/** start (seconds) of cue n (1-indexed) */
export const c = (n: number): number => cues[n - 1]?.start ?? 0;
/** end (seconds) of cue n */
export const ce = (n: number): number => cues[n - 1]?.end ?? 0;
/** start (seconds) of word k (0-indexed) in cue n */
export const cw = (n: number, k: number): number => cues[n - 1]?.words[k]?.start ?? c(n);
/** cue text */
export const ct = (n: number): string => cues[n - 1]?.text ?? '';
